import "./AddUser.css";

const AddUser = () => {
  return (
    <div>
      <form>
        <input type="text" className="text" placeholder="Name"/>
        <input type="text" className="text"/>
        <input type="text" className="text"/>
        <label >
            Choose your best photo 😉
        <input type="file" className="file" />
        </label>
        <input type="submit" />
      </form>
    </div>
  );
};

export default AddUser;
